        fuzzer_call_php_func("mb_eregi", 2, args);

        args[0] = data;
        args[1] = data;
        fuzzer_call_php_func("mb_ereg", 2, args);

        args[0] = data;
        args[1] = data;
        fuzzer_call_php_func("mb_eregi", 2, args);

        php_request_shutdown(NULL);

        free(data);
#else
        fprintf(stderr, "\n\nERROR:\nPHP built without mbstring, recompile with --enable-mbstring to use this fuzzer\n");
        exit(1);
#endif
        return 0;
}

