  5079        NODE_STATUS_ADD(node, MARK1);
  5080        {
  5081          CallNode* cn = CALL_(node);
  5082          Node* called = NODE_CALL_BODY(cn);
  5083
  5084          cn->entry_count++;
  5085
  5086          NODE_STATUS_ADD(called, CALLED);
  5087          BAG_(called)->m.entry_count++;
  5088          tune_call2_call(called);
  5089        }
  5090        NODE_STATUS_REMOVE(node, MARK1);
  5091      }
  5092      break;
  5093
  5094    default:
  5095      break;
  5096    }
  5097  }
  5098
  5099  static int
  5100  tune_call(Node* node, ScanEnv* env, int state)
  5101  {
  5102    int r;
  5103
  5104    switch (NODE_TYPE(node)) {
  5105    case NODE_LIST:
  5106    case NODE_ALT:
  5107      do {
  5108        r = tune_call(NODE_CAR(node), env, state);
  5109      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  5110      break;
  5111
  5112    case NODE_QUANT:
  5113      if (QUANT_(node)->upper == 0)
  5114        state |= IN_ZERO_REPEAT;
  5115
  5116      r = tune_call(NODE_BODY(node), env, state);
  5117      break;
  5118
  5119    case NODE_ANCHOR:
  5120      if (ANCHOR_HAS_BODY(ANCHOR_(node)))
  5121        r = tune_call(NODE_BODY(node), env, state);
  5122      else
  5123        r = 0;
  5124      break;
  5125
  5126    case NODE_BAG:
  5127      {
  5128        BagNode* en = BAG_(node);
  5129
  5130        if (en->type == BAG_MEMORY) {
  5131          if ((state & IN_ZERO_REPEAT) != 0) {
  5132            NODE_STATUS_ADD(node, IN_ZERO_REPEAT);
  5133            BAG_(node)->m.entry_count--;
  5134          }
  5135          r = tune_call(NODE_BODY(node), env, state);
  5136        }
  5137        else if (en->type == BAG_IF_ELSE) {
  5138          r = tune_call(NODE_BODY(node), env, state);
  5139          if (r != 0) return r;
  5140          if (IS_NOT_NULL(en->te.Then)) {
  5141            r = tune_call(en->te.Then, env, state);
  5142            if (r != 0) return r;
  5143          }
  5144          if (IS_NOT_NULL(en->te.Else))
  5145            r = tune_call(en->te.Else, env, state);
  5146        }
  5147        else
  5148          r = tune_call(NODE_BODY(node), env, state);
  5149      }
  5150      break;
  5151
  5152    case NODE_CALL:
  5153      if ((state & IN_ZERO_REPEAT) != 0) {
  5154        NODE_STATUS_ADD(node, IN_ZERO_REPEAT);
  5155        CALL_(node)->entry_count--;
  5156      }
  5157
  5158      r = tune_call_node_call(CALL_(node), env, state);
  5159      break;
  5160
  5161    default:
  5162      r = 0;
  5163      break;
  5164    }
  5165
  5166    return r;
  5167  }
  5168
  5169  static int
  5170  tune_call2(Node* node)
  5171  {
  5172    int r = 0;
  5173
  5174    switch (NODE_TYPE(node)) {
  5175    case NODE_LIST:
  5176    case NODE_ALT:
  5177      do {
  5178        r = tune_call2(NODE_CAR(node));
  5179      } while (r == 0 && IS_NOT_NULL(node = NODE_CDR(node)));
  5180      break;
  5181
  5182    case NODE_QUANT:
  5183      if (QUANT_(node)->upper != 0)
  5184        r = tune_call2(NODE_BODY(node));
  5185      break;
  5186
  5187    case NODE_ANCHOR:
  5188      if (ANCHOR_HAS_BODY(ANCHOR_(node)))
  5189        r = tune_call2(NODE_BODY(node));
  5190      break;
  5191
  5192    case NODE_BAG:
  5193      if (! NODE_IS_IN_ZERO_REPEAT(node))
  5194        r = tune_call2(NODE_BODY(node));
  5195
  5196      {
  5197        BagNode* en = BAG_(node);
  5198
  5199        if (r != 0) return r;
  5200        if (en->type == BAG_IF_ELSE) {
  5201          if (IS_NOT_NULL(en->te.Then)) {
  5202            r = tune_call2(en->te.Then);
  5203            if (r != 0) return r;
  5204          }
  5205          if (IS_NOT_NULL(en->te.Else))
  5206            r = tune_call2(en->te.Else);
  5207        }
  5208      }
  5209      break;
  5210
  5211    case NODE_CALL:
  5212      if (! NODE_IS_IN_ZERO_REPEAT(node)) {
  5213        tune_call2_call(node);
  5214      }
  5215      break;
  5216
  5217    default:
  5218      break;
  5219    }
  5220
  5221    return r;
  5222  }
