  5406  static int
  5407  tune_anchor(Node* node, regex_t* reg, int state, ScanEnv* env)
  5408  {
  5409    int r;
  5410    AnchorNode* an = ANCHOR_(node);
  5411
  5412    switch (an->type) {
  5413    case ANCR_PREC_READ:
  5414      r = tune_tree(NODE_ANCHOR_BODY(an), reg, state, env);
  5415      break;
  5416    case ANCR_PREC_READ_NOT:
  5417      r = tune_tree(NODE_ANCHOR_BODY(an), reg, (state | IN_NOT), env);
  5418      break;
  5419
  5420    case ANCR_LOOK_BEHIND:
  5421    case ANCR_LOOK_BEHIND_NOT:
  5422      r = check_node_in_look_behind(NODE_ANCHOR_BODY(an),
  5423                                    an->type == ANCR_LOOK_BEHIND_NOT ? 1 : 0);
  5424      if (r < 0) return r;
  5425      if (r > 0) return ONIGERR_INVALID_LOOK_BEHIND_PATTERN;
  5426      r = tune_look_behind(node, reg, state, env);
  5427      break;
  5428
  5429    default:
  5430      r = 0;
  5431      break;
  5432    }
  5433
  5434    return r;
  5435  }
